-- ...and the `ADD COLUMN` route, so all three implicit-sequence sites read the
-- declared name through the same gate.
-- @setup
CREATE TABLE acdsn (a INT);
ALTER TABLE acdsn ADD COLUMN id INT GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME acdsn_custom);
SELECT setval('acdsn_custom', 4, true);
INSERT INTO acdsn (a, id) VALUES (1, DEFAULT);
-- @test
SELECT id FROM acdsn;
